node_t *get_intersection(node_t *a, node_t *b)
{
    if (!a || !b) return NULL;

    /* 第一步：计算两个链表的长度 */
    int la = 1, lb = 1;
    for (node_t *p = a; p->next; p++) la++;
    for (node_t *p = b; p->next; p++) lb++;

    /* 尾部不同则不相交 */
    if (p->next && q->next) {
