    }

    /* 重新整理 */
    node_t *ta = a, *tb = b;
    while (ta->next) ta = ta->next;
    while (tb->next) tb = tb->next;
    if (ta != tb) return NULL;              /* 尾部不同，不相交 */

    /* 第二步：长的链表先走差值步 */
    int diff = la - lb;
    if (diff < 0) { diff = -diff; b = a; a = b; }  /* 确保 a 是较长的 */
    while (diff--) a = a->next;

    /* 第三步：同时走，相遇即为交点 */
    while (a != b) {
        a = a->next;
        b = b->next;
    }
    return a;
}
