**修正后的完整版本**：
```c
node_t *get_intersection(node_t *a, node_t *b)
{
    if (!a || !b) return NULL;

    /* 计算长度并找到尾部 */
    node_t *ta = a, *tb = b;
    int la = 1, lb = 1;
    while (ta->next) { ta = ta->next; la++; }
    while (tb->next) { tb = tb->next; lb++; }

    /* 尾部不同 → 不相交（Y 形链表尾部必须相同） */
    if (ta != tb) return NULL;

    /* 让长的链表先走差值步 */
    int diff = la - lb;
    if (diff < 0) { diff = -diff; node_t *tmp = a; a = b; b = tmp; }
    while (diff--) a = a->next;

    /* 同时走，相遇即为交点 */
    while (a != b) {
        a = a->next;
        b = b->next;
    }
    return a;
}
```

**要点**：

1. **为什么看尾部就能判断相交**。如果两个链表相交，从交点开始它们共享相同的节点序列，**尾部必然是同一个节点**。如果尾部不同，说明它们是两条完全独立的链表。

2. **为什么要先对齐**。假设链表 A 长 10 个节点，链表 B 长 7 个节点，交点在 B 的第 2 个节点（从头数）。如果同时从头开始走，A 走到交点时 B 才走到第 3 个节点，永远追不上。所以**必须让长的链表先走差值步**。

3. **时间复杂度 O(m+n)，空间 O(1)**。两次遍历，不额外分配。

**面试追问方向**：
- **如果链表有环怎么办**？情况更复杂：两个链表可能在环外相交、在环内相交、或者一个有环一个无环
- **能不能只用一次遍历**？有一种巧妙的方法叫**双指针交替法**：让 a 遍历完自己的链表后跳到 b 的头，b 遍历完自己的链表后跳到 a 的头。如果相交，两个指针会在交点相遇（因为 `la + lb` 的总路程相等）。
- **如果链表节点带有环，如何找到环的入口**？快慢指针法——相遇后让一个指针回到头，两个指针每次都走一步，再次相遇就是入口

**双指针交替法的代码**（面试加分项）：
```c
node_t *get_intersection_fast(node_t *a, node_t *b)
{
    node_t *pa = a, *pb = b;
    while (pa != pb) {
        pa = pa ? pa->next : b;
        pb = pb ? pb->next : a;
    }
    return pa;
}
```
`pa` 走的路径是 `a → b`，`pb` 走的路径是 `b → a`，总长度都是 `la + lb`。如果相交，它们必然在交点相遇；如果不相交，它们会在 NULL 相遇（返回 NULL）。

```c
#include <limits.h>

char *my_itoa(int val, char *buf, size_t size)
{
    if (!buf || size < 2) return buf;

    /* 预留空间：最多 11 个字符（"-" + 10 位数字 + "\0"） */
    if (size < 12) return buf;

    int neg = 0;
    if (val < 0) {
        /* 关键：INT_MIN 的绝对值是 2147483648，超过 INT_MAX */
        /* 不能用 abs(val)，会溢出 */
        neg = 1;
        val = -(val + 1);                       /* val = -val - 1，避免溢出 */
    }

    /* 逐位提取，从低位到高位 */
    char *p = buf;
    do {
        *p++ = (val % 10) + '0';
        val /= 10;
    } while (val > 0);

    /* 如果是负数，补上 "-"（此时 val == 1，因为 INT_MIN 被减了 1） */
    if (neg) *p++ = '-';

    /* 反转 */
    size_t len = p - buf;
    for (size_t i = 0, j = len - 1; i < j; i++, j--)
    {
        char t = buf[i]; buf[i] = buf[j]; buf[j] = t;
    }

    *p = '\0';
    return buf;
}
```

**INT_MIN 的陷阱**：

`INT_MIN = -2147483648`，它的绝对值是 `2147483648`，超过了 `INT_MAX = 2147483647`。所以 `abs(INT_MIN)` 是未定义行为（UB）。

**解决办法**：
```c
val = -(val + 1);    /* INT_MIN → 2147483647 */
```
这样 `val` 变成了正数 2147483647。然后在末尾补上 `'-'` 即可。注意这里 `-(val + 1)` 的写法——先加 1 再取反，避免了 `-(INT_MIN)` 这个 UB。

**另一种更简洁的写法（全程用负数累加）**：
```c
char *my_itoa(int val, char *buf, size_t size)
{
    if (!buf || size < 12) return buf;

    int neg = 0;
    if (val < 0) { neg = 1; val = -val; }  /* INT_MIN 取反后是 -2147483648，仍然是负数 */

    char *p = buf;
    do {
        *p++ = (char)('0' - (val % 10));    /* 用减法，因为是负数 */
        val /= 10;
    } while (val != 0);

    if (neg) *p++ = '-';

    /* 反转 */
    size_t len = p - buf;
    for (size_t i = 0, j = len - 1; i < j; i++, j--)
    {
        char t = buf[i]; buf[i] = buf[j]; buf[j] = t;
    }
    *p = '\0';
    return buf;
}
```

**这个写法的关键**：`val % 10` 对负数的结果是**负的余数**（C99 规定），比如 `-123 % 10 = -3`。所以 `'0' - (val % 10)` 得到 `'3'`，不需要 `+` 号。

**要点**：

1. **缓冲区大小必须检查**。`int` 转字符串最长 12 字节（"-" + 10 位数字 + "\0"），所以至少要 12 字节。

2. **用 `do-while` 而不是 `while`**。这样可以正确处理 `val = 0` 的情况——`do-while` 至少执行一次，输出 `"0"`。如果用 `while`，`0 % 10 = 0` 但 `val = 0` 会直接退出循环，输出空字符串。

3. **为什么要反转**。`123 % 10 = 3`，先得到的是最低位，所以生成的字符串是 `"321"`，需要反转。

**嵌入式实际使用 itoa 的场景**：

- **LCD/OLED 屏幕显示传感器数值**
- **CAN 报文的状态码转字符串用于调试**
- **日志系统中格式化整数输出**
- **Bootloader 中版本号显示**

**为什么不用 sprintf**：`sprintf(buf, "%d", val)` 在嵌入式中代价太大——链接完整的 printf 实现可能增加 20-40KB Flash，而 itoa 只有十几行代码。

```c
#define MAX_TIMERS 32

typedef struct {
    uint32_t expire_ms;     /* 到期时间戳（毫秒） */
    void    *user_data;     /* 用户回调关联的数据 */
    int      enabled;       /* 是否仍有效 */
} timer_t;

typedef struct {
    timer_t  heap[MAX_TIMERS];
    uint8_t  size;
} timer_mgr_t;

/* ---------- 堆操作 ---------- */

static void swim(timer_mgr_t *mgr, int i)
{
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (mgr->heap[parent].expire_ms > mgr->heap[i].expire_ms) {
            timer_t tmp = mgr->heap[parent];
            mgr->heap[parent] = mgr->heap[i];
            mgr->heap[i] = tmp;
            i = parent;
        } else {
            break;
        }
    }
}

static void sink(timer_mgr_t *mgr, int i)
{
    while (1) {
        int smallest = i;
        int left  = 2 * i + 1;
        int right = 2 * i + 2;

        if (left < mgr->size && mgr->heap[left].expire_ms < mgr->heap[smallest].expire_ms)
            smallest = left;
        if (right < mgr->size && mgr->heap[right].expire_ms < mgr->heap[smallest].expire_ms)
            smallest = right;

        if (smallest != i) {
            timer_t tmp = mgr->heap[i];
            mgr->heap[i] = mgr->heap[smallest];
            mgr->heap[smallest] = tmp;
            i = smallest;
        } else {
            break;
        }
    }
}

/* ---------- 公开接口 ---------- */

int timer_add(timer_mgr_t *mgr, uint32_t delay_ms, void *data)
{
    if (mgr->size >= MAX_TIMERS) return -1;

    mgr->heap[mgr->size].expire_ms = get_tick_ms() + delay_ms;
    mgr->heap[mgr->size].user_data = data;
    mgr->heap[mgr->size].enabled = 1;
    swim(mgr, mgr->size++);
    return 0;
}

int timer_remove(timer_mgr_t *mgr, int index)
{
    if (index < 0 || index >= mgr->size) return -1;

    /* 交换到末尾并弹出（O(1) 删除，但会打乱堆序）*/
    mgr->heap[index] = mgr->heap[--mgr->size];
    /* 重新调整：可能需要上浮或下沉 */
    swim(mgr, index);
    sink(mgr, index);
    return 0;
}

/* 取所有已到期的定时器 */
int timer_expire(timer_mgr_t *mgr, uint32_t now_ms, timer_t *out, int max_out)
{
    int count = 0;
    while (mgr->size > 0 && mgr->heap[0].expire_ms <= now_ms && count < max_out) {
        out[count++] = mgr->heap[0];
        mgr->heap[0].enabled = 0;               /* 标记已消费 */
        mgr->heap[0] = mgr->heap[--mgr->size];  /* 弹出堆顶 */
        sink(mgr, 0);                           /* 恢复堆序 */
    }
    return count;
}
```

**要点**：

1. **为什么用最小堆**。最小堆的堆顶始终是**最早到期**的定时器，取到期定时器是 O(1) 的。添加是 O(log n)，删除是 O(log n)。

2. **数组实现而不是指针实现**。静态数组 `MAX_TIMERS` 个元素，下标 i 的左右子节点分别是 `2i+1` 和 `2i+2`，父节点是 `(i-1)/2`。**零内存分配**，符合嵌入式要求。

3. **enabled 标志的作用**。定时器的到期时间可能因为重新调度而改变，或者用户可能在定时器到期前取消它。标记 `enabled = 0` 后可以跳过执行回调，而不必从堆中立即删除（删除是 O(log n)，标记是 O(1)）。

4. **timer_remove 的实现细节**。先把要删除的元素和末尾元素交换，再 pop。但交换过来的元素可能破坏堆序，所以需要 `swim` + `sink` 重新调整。实际上只需要其中一个（根据交换来的元素和原位置元素的大小关系决定），但两个都调是安全的。

**嵌入式实际使用**：

- **FreeRTOS 的 vTaskDelayUntil / vTaskDelay** 底层就用类似机制
- **STM32 的软件定时器**（比如 HAL 库的 `HAL_Delay` 配合超时轮询）
- **CAN 诊断的超时控制**（比如 ISO-TP 帧间隔超时）
- **看门狗的重载计时**

**可能的追问**：
- **如果要支持高精度微秒级定时器怎么办**？用 64 位时间戳，或者用硬件定时器 + 软件补偿
- **如果要支持周期性定时器（到期后自动重启）怎么办**？在 `timer_expire` 中检测到到期时，根据周期重新计算 `expire_ms`
- **如果定时器数量很大（几千个）怎么办**？最小堆的 O(log n) 增长很慢，1000 个定时器只需要 10 层，依然很快。但如果需要频繁插入删除，可以用**配对堆**或**斐波那契堆**

```c
#include <stddef.h>

typedef struct list_node {
    struct list_node *prev;
    struct list_node *next;
} list_node_t;

#define LIST_HEAD_INIT(name) { &(name), &(name) }
#define LIST_HEAD(name)      list_node_t name = LIST_HEAD_INIT(name)

static inline void list_init(list_node_t *h)
{
    h->prev = h->next = h;
}

static inline void list_add(list_node_t *h, list_node_t *n)
{
    n->next     = h->next;
    n->prev     = h;
    h->next->prev = n;
    h->next     = n;
}

static inline void list_del(list_node_t *n)
{
    n->prev->next = n->next;
    n->next->prev = n->prev;
    n->prev = n->next = NULL;                   /* 安全清理 */
}

static inline int list_empty(const list_node_t *h)
{
    return h->next == h;
}

/* 从 list_node_t 指针反推包含它的结构体指针 */
#define list_entry(ptr, type, member)  \
    ((type *)((char *)(ptr) - offsetof(type, member)))

/* 遍历宏 */
#define list_for_each(pos, head) \
    for (pos = (head)->next; pos != (head); pos = pos->next)

#define list_for_each_safe(pos, tmp, head) \
    for (pos = (head)->next, tmp = pos->next; \
         pos != (head); \
         pos = tmp, tmp = pos->next)
```

**使用示例**：
```c
typedef struct {
    int id;
    char name[32];
    list_node_t list;     /* 内嵌的链表节点 */
} device_t;

LIST_HEAD(devices);

device_t *dev = malloc(...);
list_add(&devices, &dev->list);   /* 插入 */

list_node_t *pos;
list_for_each(pos, &devices) {
    device_t *d = list_entry(pos, device_t, list);   /* 拿到 device_t 指针 */
    printf("id=%d, name=%s\n", d->id, d->name);
}
```

**设计要点**：

1. **为什么 list_head 是空的**。`list_head` 只存两个指针，不含数据。这样它可以被**嵌入到任何结构体中**，与结构体本身的内容无关。这是 Linux 内核链表设计的核心思想——**链表与数据分离**。

2. **`container_of`（即 list_entry）的原理**。已知某个成员的地址 `ptr`，减去该成员在结构体中的偏移 `offsetof(type, member)`，就得到了结构体的起始地址。`offsetof` 通过 `(type *)0->member` 获取偏移。

3. **为什么 `list_for_each_safe` 需要两个指针**。如果在遍历时调用 `list_del(pos)`，`pos` 已经被 unlink，`pos->next` 是无效的（被设为 NULL）。所以需要提前保存 `tmp = pos->next`。

4. **双向循环链表的特性**。头节点的 `prev` 指向最后一个节点，`next` 指向第一个节点。遍历到头就回到头，不需要额外判断。这使得**插入和删除操作的代码完全对称且简洁**。

5. **为什么 Linux 内核大量使用这种设计**。因为内核中有大量不同结构体（socket、inode、task_struct 等）需要被组织成链表。如果把链表节点放在结构体内部，就可以**不用修改原有结构体**就给它加上链表功能——这正是"内嵌式"的优势。

**嵌入式实际使用**：

- **你的 i.MX6ULL 语音终端**中，音频缓冲区可以用链表组织，播放线程和采集线程各自操作
- **STM32 传感器节点**中，传感器驱动注册表可以用这种链表实现
- **多协议工业网关**中，每个通信通道（RS485、CAN、MQTT）的信息结构可以挂在同一个链表上统一管理

**面试追问方向**：
- **list_entry 为什么用 `char *` 而不是 `void *`**？`void *` 不能做指针算术（没有字节级的步长），必须转成 `char *` 才能减偏移
- **list_del 之后为什么要把 prev/next 置 NULL**？防止悬垂指针继续使用，这是安全最佳实践（虽然内核代码中经常省略这一步以追求极致性能）
- **如果遍历中要删除多个节点怎么办**？用 `list_for_each_safe`，或者先收集待删除的节点再统一删除

```c
#include <ctype.h>

int parse_args(const char *cmd, char **argv, int max_argc)
{
    int argc = 0;
    const char *p = cmd;

    while (*p && argc < max_argc) {
        /* 跳过前导空格 */
        while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
        if (!*p) break;

        argv[argc++] = (char *)p;

        if (*p == '\'' || *p == '"') {
            /* 引号包裹的参数：找匹配的结束引号 */
            char quote = *p;
            p++;
            while (*p && *p != quote) p++;
            if (*p) {
                *p = '\0';    /* 替换结束引号为 NUL */
                p++;
            }
        } else {
            /* 无引号：遇到空格或 NUL 结束 */
            while (*p && *p != ' ' && *p != '\t' && *p != '\n' && *p != '\r')
                p++;
            if (*p) *p++ = '\0';
        }
    }
    return argc;
}
```

**要点**：

1. **引号的处理方式**：找到匹配的结束引号后，**直接把引号替换成 `\0`**，这样 `argv[i]` 就是一个合法的 C 字符串。不需要分配新内存，不需要拷贝。

2. **只处理引号内的内容**。单引号和双引号在解析逻辑上是一样的（不像 bash 中双引号支持变量展开）。如果需要支持 bash 语义，需要额外的解析逻辑。

3. **未闭合的引号处理**。当前实现中，如果引号没有闭合，`*p` 为 `\0` 时退出循环，引号前的所有内容作为一个参数返回。这是合理的容错行为。

4. **argv 数组由调用者提供**。这样不需要 `malloc`，适合嵌入式环境。调用者需要保证 `argv` 有足够的空间（比如 `char *argv[64]`）。

**使用示例**：
```c
char buf[] = "sensor start "mode auto" 'debug on'";
char *argv[64];
int argc = parse_args(buf, argv, 64);
/* argc == 4, argv[0]="sensor", argv[1]="start", argv[2]="mode auto", argv[3]="debug on" */
```

**嵌入式实际使用场景**：

- **串口命令解析**：终端用户通过串口输入 `sensor start "mode auto"`，解析后执行对应动作
- **AT 命令解析**：`AT+CMD=param1 "param with space" param3`
- **配置文件解析**：INI 文件中带引号的值
- **你的 ECU 诊断系统**中，PC 端发出的 UDS 诊断命令如果是文本格式的，也可以用类似的解析器

**面试追问方向**：
- **怎么处理转义字符（如 `"he said \\\"hi\\\""`）**？需要额外的状态机处理 `\` 转义
- **怎么处理 `=` 赋值（如 `param=value`）**？在解析出参数后，再按 `=` 拆分
- **如果参数中包含空格但没有引号怎么办**？当前实现中空格就是分隔符，无法表示带空格的参数。这是 shell 解析器的一个经典设计选择

**扩展**：如果要做完整的 shell 解析器，还需要处理：
- `\` 转义
- `$variable` 展开
- `$(command)` 子命令
- `&&`、`||`、`|` 管道
- 重定向 `>`、`<`

但这些在嵌入式中很少需要，通常只需要基本的引号处理就够了。

