```c
#include <stdio.h>

static void swap(int *a, int *b) {
    int tmp = *a; *a = *b; *b = tmp;
}

/* Lomuto 分区，以 arr[hi] 为主元 */
static int partition(int arr[], int lo, int hi) {
    int pivot = arr[hi];
    int i = lo;
    for (int j = lo; j < hi; j++) {
        if (arr[j] <= pivot) { swap(&arr[i], &arr[j]); i++; }
    }
    swap(&arr[i], &arr[hi]);
    return i;
}

static void quicksort(int arr[], int lo, int hi) {
    if (lo >= hi) return;
    /* 小数组切换插入排序，减少递归开销 */
    if (hi - lo < 8) {
        for (int i = lo + 1; i <= hi; i++) {
            int key = arr[i], j = i - 1;
            while (j >= lo && arr[j] > key) { arr[j+1] = arr[j]; j--; }
            arr[j+1] = key;
        }
        return;
    }
    /* 三数取中：把中位数换到 hi 位置作为主元 */
    int mid = lo + (hi - lo) / 2;
    if (arr[lo] > arr[mid]) swap(&arr[lo], &arr[mid]);
    if (arr[lo] > arr[hi])  swap(&arr[lo], &arr[hi]);
    if (arr[mid] > arr[hi]) swap(&arr[mid], &arr[hi]);
    /* 此时 arr[hi] 已是三者的中位数，直接分区 */
    int p = partition(arr, lo, hi);
    /* 先递归小的那半，尾递归优化栈深度 */
    if (p - lo < hi - p) {
        quicksort(arr, lo, p - 1);
        quicksort(arr, p + 1, hi);  /* 可改成 lo=p+1 的循环以消除尾递归 */
    } else {
        quicksort(arr, p + 1, hi);
        quicksort(arr, lo, p - 1);
    }
}

int main(void) {
    int arr[] = {64, 34, 25, 12, 22, 11, 90, -5, 0, 47};
    int n = (int)(sizeof(arr) / sizeof(arr[0]));

    printf("排序前: ");
    for (int i = 0; i < n; i++) printf("%d ", arr[i]);
    printf("\n");

    quicksort(arr, 0, n - 1);

    printf("排序后: ");
    for (int i = 0; i < n; i++) printf("%d ", arr[i]);
    printf("\n");
    return 0;
}
```

**时间复杂度**：平均 O(n log n)，最坏 O(n²)（已排序 + 固定主元时）。**空间**：O(log n) 递归栈。

**三个工程优化点**：
1. **三数取中**：避免已排序数组退化成 O(n²)。
2. **小数组切插入排序**：n < 8 时插入排序常数因子更好（无递归、缓存友好）。
3. **先递归小的那半**：保证递归深度最坏也是 O(log n)，防止栈溢出。

**嵌入式选型建议**：实时系统不推荐快排，因为最坏 O(n²) 不可预测。传感器数据排序（小 n）用插入排序；需要最坏保证时用堆排序（O(n log n) 保证且无递归）。

```c
#include <stdio.h>
#include <stdint.h>
#include <string.h>

/*
 * 免锁环形缓冲区（SPSC: Single Producer Single Consumer）
 * 约束：BUF_SIZE 必须是 2 的幂
 */
#define BUF_SIZE  256u
#define BUF_MASK  (BUF_SIZE - 1u)

typedef struct {
    uint8_t          data[BUF_SIZE];
    volatile uint8_t head;   /* 生产者维护，只有生产者写 */
    volatile uint8_t tail;   /* 消费者维护，只有消费者写 */
} RingBuf;

void     ring_init(RingBuf *rb) { rb->head = rb->tail = 0; }
int      ring_empty(const RingBuf *rb) { return rb->head == rb->tail; }
int      ring_full(const RingBuf *rb)  { return (uint8_t)(rb->head - rb->tail) == BUF_SIZE; }
uint8_t  ring_count(const RingBuf *rb) { return (uint8_t)(rb->head - rb->tail); }

/* push：写一个字节，满时返回 -1 */
int ring_push(RingBuf *rb, uint8_t byte) {
    if (ring_full(rb)) return -1;
    rb->data[rb->head & BUF_MASK] = byte; /* 1. 先写数据 */
    rb->head++;                            /* 2. 再更新索引（消费者才能看到新数据）*/
    return 0;
}

/* pop：读一个字节，空时返回 -1 */
int ring_pop(RingBuf *rb, uint8_t *out) {
    if (ring_empty(rb)) return -1;
    *out = rb->data[rb->tail & BUF_MASK]; /* 1. 先读数据 */
    rb->tail++;                            /* 2. 再更新索引（生产者才能看到空间释放）*/
    return 0;
}

int main(void) {
    RingBuf rb;
    ring_init(&rb);
    uint8_t v;

    /* 写入 */
    for (uint8_t i = 1; i <= 5; i++)
        printf("push %d: %s\n", i, ring_push(&rb, i) == 0 ? "ok" : "full");
    printf("count=%d\n", ring_count(&rb));

    /* 读取 */
    while (!ring_empty(&rb)) {
        ring_pop(&rb, &v);
        printf("pop: %d\n", v);
    }

    /* 测试满的情况 */
    for (int i = 0; i < (int)BUF_SIZE; i++) ring_push(&rb, (uint8_t)i);
    printf("full=%d, next push=%d\n", ring_full(&rb), ring_push(&rb, 0xFF));
    return 0;
}
```

**免锁原理**：
- `head` 只有生产者写，消费者只读；`tail` 只有消费者写，生产者只读。**没有两个执行流同时写同一个变量**，不存在读-改-写竞争。
- 写顺序：**先写 data，再更新 head**。反过来的话消费者会看到 head 前进但数据还没写好。
- `volatile` 防止编译器把索引缓存在寄存器里，确保每次都真正读内存。

**BUF_SIZE 为什么必须是 2 的幂**：
- `& BUF_MASK` 代替 `% BUF_SIZE`（位操作比除法快，MCU 无硬件除法器时差距尤为明显）
- `uint8_t` 自然溢出回绕到 0，配合 2 的幂大小，`head - tail` 永远是正确的数据量

**典型应用**：串口 ISR 往 ring 里塞字节，主循环/任务从 ring 里取——ISR 与主流程解耦的标准模式。

**标准规定这是未定义行为**，实际表现通常是**只调用基类析构函数**，派生类新增的成员不被析构。

```cpp
class Base { public: ~Base() {} };                    /* 非虚，危险 */
class Derived : public Base {
    char *buf;
public:
    Derived() { buf = new char[1024]; }
    ~Derived() { delete[] buf; }                      /* 永远不会被调用 */
};

Base *p = new Derived();
delete p;                                             /* 泄漏 1024 字节 */
```

**正确做法**：
```cpp
class Base {
public:
    virtual ~Base() = default;   /* 打算被继承 → 虚析构 */
};
```

**判断规则**：
- **一个类如果有任何虚函数，析构函数就应该是虚的**（说明它设计上就是要被继承和多态使用的）
- **打算被继承并通过基类指针删除** → 虚析构
- **不打算被继承** → 可以标 `final`，编译器还能做去虚化优化
- **打算被继承但不通过基类指针删除**（如策略基类）→ 可以用 `protected` 非虚析构，让编译期就禁止 `delete base_ptr`

**嵌入式的额外考虑**：虚析构会引入 vtable，如果整个类原本没有虚函数，加一个虚析构就多了 vptr 和 vtable 的开销。所以**基类的设计意图要明确**：是接口类（该有虚析构）还是纯粹的代码复用（可能不该用公有继承，用组合更好）。

**常见的现实后果**：这类泄漏在短生命周期程序里看不出来，但嵌入式设备连续跑几个月，反复创建销毁对象，最终堆耗尽。而且泄漏点和崩溃点毫无关联，极难定位。

**RAII（Resource Acquisition Is Initialization，资源获取即初始化）**：把资源的生命周期绑定到对象的生命周期上——**构造函数获取资源，析构函数释放资源**。对象离开作用域时析构函数自动执行，资源必然被释放。

```cpp
class ScopedLock {
    pthread_mutex_t *m;
public:
    explicit ScopedLock(pthread_mutex_t *mtx) : m(mtx) { pthread_mutex_lock(m); }
    ~ScopedLock() { pthread_mutex_unlock(m); }
    ScopedLock(const ScopedLock&) = delete;          /* 禁止拷贝 */
    ScopedLock& operator=(const ScopedLock&) = delete;
};

void foo() {
    ScopedLock lk(&mtx);
    if (error) return;        /* 提前返回也会解锁 */
    if (other)  throw ...;    /* 抛异常也会解锁 */
}                             /* 正常退出同样解锁 */
```

**核心价值：消除"忘记释放"这一整类 bug。** C 语言里典型的
```c
lock(); 
if (err) { unlock(); return -1; }   /* 每条退出路径都要记得 */
if (err2) { unlock(); return -2; }  /* 漏一条就死锁 */
unlock();
```
随着函数变复杂，漏掉某条路径几乎是必然的。RAII 从语言机制上保证了不会漏。

**嵌入式里的典型应用**：
- **锁**（`std::lock_guard`、`std::unique_lock`）
- **动态内存**（`std::unique_ptr`、`std::shared_ptr`）
- **文件/设备描述符**：构造时 open，析构时 close
- **临界区**：构造时关中断（保存 PRIMASK），析构时恢复。这个特别好用，因为"保存并恢复原状态"的逻辑容易写错
- **外设使能**：构造时使能时钟/片选，析构时关闭

**注意事项**：
1. **析构函数里不要抛异常**。析构可能在异常展开过程中被调用，此时再抛会直接 `std::terminate`
2. **RAII 对象要禁止拷贝**（或实现移动语义），否则双重释放
3. **嵌入式禁用异常时 RAII 依然有价值**——它对付的主要是多路径返回，异常只是其中一种

RAII 是 C++ 相比 C 最值得引入嵌入式的特性之一，而且**零运行时开销**（析构调用是编译期确定的）。

**问题**：C++11 之前，返回或传递大对象会产生**深拷贝**——分配新内存、逐字节复制、释放旧内存。而很多时候源对象马上就要销毁了，这个拷贝完全是浪费。

**移动语义**：对于**即将销毁的临时对象**，不拷贝其资源，而是**把资源的所有权"偷"过来**，把源对象置为可安全析构的空状态。

```cpp
class Buffer {
    char *data; size_t size;
public:
    /* 拷贝构造：真的复制一份 */
    Buffer(const Buffer &o) : size(o.size) {
        data = new char[size];
        memcpy(data, o.data, size);
    }
    /* 移动构造：偷指针，O(1) */
    Buffer(Buffer &&o) noexcept : data(o.data), size(o.size) {
        o.data = nullptr;      /* 关键：源对象置空，避免双重释放 */
        o.size = 0;
    }
    ~Buffer() { delete[] data; }
};
```

**核心区别**：拷贝是 O(n)（复制 n 字节），移动是 O(1)（复制几个指针）。

**右值引用 `&&`**：
- **左值**：有名字、能取地址的对象
- **右值**：临时对象、字面量，即将消亡
- `T&&` 只能绑定右值，编译器据此选择移动版本而非拷贝版本
- **`std::move` 不移动任何东西**，它只是把左值**强制转换成右值引用**，从而让重载决议选中移动版本。名字有误导性

**几个要点**：
1. **移动构造函数一定要加 `noexcept`**。标准容器（如 `vector`）在扩容时，只有确认移动不会抛异常才会用移动，否则退回到拷贝以保证异常安全。忘了加 noexcept，vector 扩容的性能优化就白费了。
2. **被移动后的对象处于"有效但未指定"的状态**，只能安全析构或重新赋值，不能假设它还有原来的内容。
3. **返回局部对象不需要写 `std::move`**。编译器有 RVO/NRVO（返回值优化），直接在调用者的空间构造，连移动都省了。写了 `return std::move(x)` 反而会**阻止 RVO**，是常见的反模式。

**嵌入式里的意义**：如果项目里有管理资源的类（缓冲区、文件句柄、设备句柄），移动语义能显著减少不必要的资源复制。但如果整个项目都是静态分配、没有堆，移动语义的价值就有限了。

**价值：零开销抽象。** 模板在**编译期**展开，生成的是针对具体类型的专用代码，运行期**没有任何间接调用或类型判断**。这是它相比虚函数的核心优势。

**典型应用**：

**1. 编译期确定的硬件抽象**
```cpp
template <uint32_t BASE>
class Gpio {
public:
    static void set(uint8_t pin) {
        reinterpret_cast<volatile uint32_t*>(BASE)[BSRR/4] = (1u << pin);
    }
};
using PortA = Gpio<GPIOA_BASE>;
PortA::set(5);     /* 编译后就是一条 STR 指令，和手写寄存器操作一样快 */
```

**2. 编译期计算**：配合 constexpr 生成查找表、计算滤波系数。

**3. 类型安全的容器**：固定容量的环形缓冲、静态队列，容量作为模板参数，编译期确定，无动态分配。

**4. CRTP 实现静态多态**：
```cpp
template <typename Derived>
class DriverBase {
public:
    void init() { static_cast<Derived*>(this)->do_init(); }   /* 编译期绑定，可内联 */
};
class UartDriver : public DriverBase<UartDriver> {
    friend class DriverBase<UartDriver>;
    void do_init() { /* ... */ }
};
```
拿到了多态的表达力，但**没有 vtable、没有间接调用、可以完全内联**。

**代码膨胀的成因**：每种模板参数组合都生成一份独立代码。`Buffer<uint8_t>`、`Buffer<uint16_t>`、`Buffer<uint32_t>` 是三份完全独立的机器码。

**控制手段**：

1. **把与类型无关的逻辑抽到非模板基类**（"瘦模板"模式）：
```cpp
class VectorBase {                     /* 不含类型信息的通用逻辑 */
protected:
    void *data; size_t size, cap;
    void grow(size_t elem_size);       /* 只编译一份 */
};
template <typename T>
class Vector : private VectorBase {    /* 薄薄一层类型转换 */
public:
    void push_back(const T &v) { if (size == cap) grow(sizeof(T)); ... }
};
```

2. **显式实例化**：在一个 .cpp 里 `template class Buffer<uint8_t>;`，其他地方用 `extern template` 声明，避免每个编译单元都实例化一份。

3. **减少模板参数的组合数**：非必要不参数化。

4. **链接器帮忙**：`-ffunction-sections -fdata-sections` + `-Wl,--gc-sections` 能去掉未使用的实例化；相同的函数体还可能被 `--icf`（identical code folding）合并。

5. **实测**：编译后看 map 文件，找出体积最大的符号，用 `c++filt` 解开修饰名，看看是不是某个模板实例化爆了。

**结论**：模板在嵌入式里是**性能友好但体积需要留意**的特性。做法是用，但要**看着 map 文件用**。

